import{_ as e,c as t,o as i,am as l}from"./chunks/framework.83COwwOK.js";const _=JSON.parse('{"title":"关于 Pogget 用户知情权的说明","description":"","frontmatter":{},"headers":[],"relativePath":"agreement/pogget-service.md","filePath":"agreement/pogget-service.md"}'),r={name:"agreement/pogget-service.md"};function o(n,a,h,c,d,s){return i(),t("div",null,a[0]||(a[0]=[l('<h1 id="关于-pogget-用户知情权的说明" tabindex="-1">关于 Pogget 用户知情权的说明 <a class="header-anchor" href="#关于-pogget-用户知情权的说明" aria-label="Permalink to &quot;关于 Pogget 用户知情权的说明&quot;">​</a></h1><p>为保障您（以下简称“用户”）在使用 Pogget（以下简称“本应用”）过程中的知情权，并明确 Vilinko （以下简称“我们”）在提供服务时可能涉及的数据处理范围，我们依据《服务条款》及《隐私政策》制定本说明。</p><h2 id="一、用户权利说明" tabindex="-1">一、用户权利说明 <a class="header-anchor" href="#一、用户权利说明" aria-label="Permalink to &quot;一、用户权利说明&quot;">​</a></h2><h3 id="_1-个人使用授权" tabindex="-1">1. 个人使用授权 <a class="header-anchor" href="#_1-个人使用授权" aria-label="Permalink to &quot;1. 个人使用授权&quot;">​</a></h3><p>我们授予您一项个人的、不可转让的、非独占的许可，允许您出于个人学习、研究及、娱乐及工作(非统一部署)等非商业目的使用本应用及相关功能。如需在商业环境中使用本应用或需要任何特定功能的修改，您应事先联系我们获取正式的书面授权。(正式联系邮箱:contact@vilinko.com，亦可直接在B站等渠道联系)</p><h3 id="_2-非商业性分享授权" tabindex="-1">2. 非商业性分享授权 <a class="header-anchor" href="#_2-非商业性分享授权" aria-label="Permalink to &quot;2. 非商业性分享授权&quot;">​</a></h3><p>在确保应用内容完整、版权信息清晰的前提下，您可通过第三方平台或渠道以非商业目的分享本应用。严禁篡改本程序，包括但不限于嵌入恶意代码、擅自修改署名信息等危害用户信息安全或侵犯权利的行为，我们对此类行为保留追究法律责任的权利。</p><h3 id="_3-衍生内容创作授权" tabindex="-1">3. 衍生内容创作授权 <a class="header-anchor" href="#_3-衍生内容创作授权" aria-label="Permalink to &quot;3. 衍生内容创作授权&quot;">​</a></h3><p>我们支持您基于本应用进行合法的二次创作，包括但不限于制作视频、撰写文章或发布博客等内容。您在创作过程中通过平台获得的分成收入，归您个人所有。若您的创作涉及品牌合作、线下出版或其他商业用途，请提前与我们联系并获得书面许可。</p><h2 id="二、数据处理说明" tabindex="-1">二、数据处理说明 <a class="header-anchor" href="#二、数据处理说明" aria-label="Permalink to &quot;二、数据处理说明&quot;">​</a></h2><p>我们高度重视用户隐私保护，在数据处理过程中始终遵循“最小必要”原则。</p><h3 id="_1-数据访问范围" tabindex="-1">1. 数据访问范围 <a class="header-anchor" href="#_1-数据访问范围" aria-label="Permalink to &quot;1. 数据访问范围&quot;">​</a></h3><ul><li>（1）用户主动授权：当您在本应用内主动添加文件或数据时，视为您授权本应用访问相关内容(您的数据储存在本地,不会同在线服务相连)；</li><li>（2）项目互通支持：为实现功能联动，本应用可能在必要时访问由 Vilinko 其他项目生成的互通数据；</li><li>（3）访问限制：除上述情形外，本应用不会访问或读取您设备中的其他私人文件、相册内容或第三方应用数据。</li></ul><h3 id="_2-运行状态信息存储" tabindex="-1">2. 运行状态信息存储 <a class="header-anchor" href="#_2-运行状态信息存储" aria-label="Permalink to &quot;2. 运行状态信息存储&quot;">​</a></h3><p>为保障应用正常运行并提供个性化体验，本应用会读写必要的运行配置和缓存信息，具体包括：</p><ul><li>（1）应用状态记录：如首次启动标识、当前版本号等；</li><li>（2）界面配置信息：如界面布局、用户自定义设置及UI状态等；</li><li>（3）性能优化数据：如临时缓存文件等。 上述信息仅用于维持应用运行，不涉及您的个人敏感信息。</li></ul><h3 id="_3-网络连接与数据使用说明" tabindex="-1">3. 网络连接与数据使用说明 <a class="header-anchor" href="#_3-网络连接与数据使用说明" aria-label="Permalink to &quot;3. 网络连接与数据使用说明&quot;">​</a></h3><p>本应用仅在以下情形中建立网络连接：</p><ul><li>（1）版本更新检查：获取最新版本信息；</li><li>（2）基础信息服务：如查看官方公告、开发者及赞助者信息；</li><li>（3）数据分析协助：在获得您明确授权后，我们可能收集与故障相关的运行信息以优化产品性能。</li></ul><p>除上述明确场景外，本应用不会通过网络收集、上传或同步您的任何数据。您的所有文件和信息均存储于设备本地。因数据不自动同步至云端，请您妥善管理和备份重要数据，避免因误操作或数据清理造成不可恢复的损失。</p>',20)]))}const u=e(r,[["render",o]]);export{_ as __pageData,u as default};
